// Thin trigger: bounded, deduplicated batch of claimable run ids.
// Duplicate schedules and restarts are already suppressed server-side via
// persisted idempotency; this guard only prevents re-sending the same id.
const payload = $input.first().json || {};
const runs = Array.isArray(payload.runs) ? payload.runs : [];
const seen = new Set();
const prepared = [];
for (const run of runs) {
  if (!run || typeof run.run_id !== 'string' || run.run_id.length === 0 || run.run_id.length > 160) continue;
  if (seen.has(run.run_id)) continue;
  seen.add(run.run_id);
  prepared.push({ run_id: run.run_id, poll_count: 0 });
  if (prepared.length >= 25) break; // bounded batch
}
return prepared.map((json) => ({ json }));

// 202 accepted -> poll; 200 replay with a terminal run -> deliver;
// anything else (transport error, unexpected shape) -> honest failure.
const TERMINAL = ['succeeded', 'limited', 'failed', 'stalled', 'superseded'];
const prepared = $('Prepare Runs').all().map((item) => item.json);
const responses = $input.all().map((item) => item.json || {});
const out = [];
for (let index = 0; index < prepared.length; index += 1) {
  const run = prepared[index];
  const response = responses[index] || {};
  if (response.error || !response.run_id) {
    out.push({ json: { run_id: run.run_id, phase: 'execute_failed' } });
  } else if (response.status === 'accepted') {
    out.push({ json: { run_id: response.run_id, phase: 'poll', poll_count: 0 } });
  } else if (response.run && TERMINAL.includes(response.run.status)) {
    out.push({ json: { run_id: response.run_id, phase: 'deliver', run: response.run } });
  } else {
    out.push({ json: { run_id: response.run_id, phase: 'poll', poll_count: 0 } });
  }
}
return out;

// Classify one poll response. Terminal statuses advance to delivery;
// everything else (including transport errors) keeps polling under the
// bounded budget. Validation rejections never loop: terminal failures
// are delivered honestly exactly once.
const previous = $('Normalize Execute Response').item.json || {};
const response = $input.item.json || {};
const TERMINAL = ['succeeded', 'limited', 'failed', 'stalled', 'superseded'];
const status = response.run && response.run.status;
if (TERMINAL.includes(status)) {
  return { json: { run_id: response.run.run_id, phase: 'deliver', run: response.run } };
}
return {
  json: {
    run_id: previous.run_id,
    phase: 'poll',
    poll_count: (previous.poll_count || 0) + 1,
  },
};

// Bounded budget exhausted: end honestly instead of polling forever.
const item = $input.item.json || {};
return { json: { run_id: item.run_id, phase: 'poll_timeout' } };

// Delivery is the persisted, server-validated state — nothing is
// invented here. Terminal success requires bound result references;
// failures and stalls require an honest error code; timeouts are labeled.
const item = $input.item.json || {};
const TERMINAL = ['succeeded', 'limited', 'failed', 'stalled', 'superseded'];
if (item.phase === 'execute_failed') {
  return { json: { run_id: item.run_id, delivery_status: 'execute_failed', delivered_at: new Date().toISOString() } };
}
if (item.phase === 'poll_timeout') {
  return { json: { run_id: item.run_id, delivery_status: 'poll_timeout', delivered_at: new Date().toISOString() } };
}
const run = item.run || {};
if (!TERMINAL.includes(run.status)) {
  throw new Error('Refusing to deliver a non-terminal research run');
}
const delivery = {
  run_id: run.run_id,
  delivery_status: run.status,
  position_id: run.position_id,
  position_revision: run.position_revision,
  delivered_at: new Date().toISOString(),
};
if (run.status === 'succeeded' || run.status === 'limited') {
  if (!run.assessment_id || !run.evidence_snapshot_id) {
    throw new Error('Terminal success without bound result references');
  }
  delivery.assessment_id = run.assessment_id;
  delivery.evidence_snapshot_id = run.evidence_snapshot_id;
} else if (run.status === 'failed' || run.status === 'stalled') {
  if (!run.error_code) {
    throw new Error('Terminal failure without an honest error code');
  }
  delivery.error_code = run.error_code;
}
return { json: delivery };

// Execution log of the delivery envelope (codes and bound references
// only — never credentials, prompts or raw payloads).
const deliveries = $input.all().map((item) => item.json);
console.log('Horizon research deliveries:', JSON.stringify(deliveries));
return deliveries.map((json) => ({ json }));
